type ThemeName = 'carmesí' | 'coral' | 'vino' | 'terracota' | 'frambuesa' | 'borgoña' | 'océano' | 'bosque' | 'lavanda' | 'ámbar'
type ColorMode = 'light' | 'dark' | 'system'

const themeOptions: { name: ThemeName; color: string; label: string }[] = [
  { name: 'carmesí', color: '#c93636', label: 'Carmesí' },
  { name: 'coral', color: '#df654d', label: 'Coral' },
  { name: 'vino', color: '#873449', label: 'Vino' },
  { name: 'terracota', color: '#b6533b', label: 'Terracota' },
  { name: 'frambuesa', color: '#bd315c', label: 'Frambuesa' },
  { name: 'borgoña', color: '#762f3a', label: 'Borgoña' },
  { name: 'océano', color: '#176b87', label: 'Océano' },
  { name: 'bosque', color: '#2f7756', label: 'Bosque' },
  { name: 'lavanda', color: '#7656a6', label: 'Lavanda' },
  { name: 'ámbar', color: '#b26a16', label: 'Ámbar' },
]

const roleLabels: Record<UserRole, string> = { tutor: 'Tutor de mascotas', business: 'Administrador de Pyme', clinical: 'Personal clínico veterinario', admin: 'Administrador PetSuite' }

function App() {
  const [user, setUser] = useState<{ name: string; role: UserRole } | null>(null)
  const [active, setActive] = useState('home')
  const [pets, setPets] = useState<Pet[]>(() => JSON.parse(localStorage.getItem('petsuite-pets') || 'null') || initialPets)
  const [selectedPet, setSelectedPet] = useState<Pet | null>(pets[0])
  const [showAdd, setShowAdd] = useState(false)
  const [qrPet, setQrPet] = useState<Pet | null>(null)
  const [theme, setTheme] = useState<ThemeName>(() => (localStorage.getItem('petsuite-theme') as ThemeName) || 'carmesí')
  const [mode, setMode] = useState<ColorMode>(() => (localStorage.getItem('petsuite-mode') as ColorMode) || 'light')
  const [brightness, setBrightness] = useState(() => Number(localStorage.getItem('petsuite-brightness')) || 100)
  const [profile, setProfile] = useState(() => JSON.parse(localStorage.getItem('petsuite-profile') || 'null') || { name: 'Ana Soto', email: 'ana@petsuite.cl', phone: '+56 9 6123 4580', avatar: 'AS' })

  useEffect(() => {
    const applyMode = () => { const dark = mode === 'dark' || (mode === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches); document.documentElement.dataset.theme = theme; document.documentElement.dataset.mode = dark ? 'dark' : 'light' }
    applyMode(); setBrightnessVariables(brightness); localStorage.setItem('petsuite-theme', theme); localStorage.setItem('petsuite-mode', mode); localStorage.setItem('petsuite-brightness', String(brightness))
    if (mode === 'system') { const media = window.matchMedia('(prefers-color-scheme: dark)'); media.addEventListener('change', applyMode); return () => media.removeEventListener('change', applyMode) }
  }, [theme, mode, brightness])

  const publicPet = window.location.hash.startsWith('#emergency/') ? pets.find(pet => pet.id === window.location.hash.slice(11)) : null
  if (!user) return publicPet ? <EmergencyView pet={publicPet} /> : <Login onLogin={(name, role) => { setUser({ name, role }); setActive(role === 'tutor' ? 'home' : role === 'business' ? 'business-home' : role === 'clinical' ? 'clinical-home' : 'admin-home') }} />

  const savePets = (next: Pet[]) => { setPets(next); localStorage.setItem('petsuite-pets', JSON.stringify(next)) }
  const addPet = (data: Pet) => { savePets([...pets, data]); setShowAdd(false); setActive('pets') }

  return (
    <div className="app-shell">
      <aside className="sidebar">
        <div className="brand"><span className="brand-mark">+</span><span>Pet<span>Suite</span></span></div>
        <div className="profile-mini"><div className="avatar">{user.name.slice(0, 2).toUpperCase()}</div><div><strong>{user.name}</strong><small>{roleLabels[user.role]}</small></div></div>
        <nav>{roleMenus[user.role].map(([label, id]) => <button className={active === id ? 'nav-item active' : 'nav-item'} onClick={() => setActive(id)} key={id}><span className="nav-icon">{id.includes('home') || id === 'home' ? '⌂' : id === 'pets' || id === 'patients' ? '♡' : id === 'directory' ? '⌖' : id === 'settings' ? '⚙' : '◌'}</span>{label}</button>)}</nav>
        <div className="sidebar-bottom" />
      </aside>
      <main className="main-content">
        <header className="topbar"><div className="mobile-brand brand"><span className="brand-mark">+</span><span>Pet<span>Suite</span></span></div><div className="top-actions"><button className="icon-button">⌕</button><button className="icon-button notification">♧<i /></button><div className="avatar small">{user.name.slice(0, 2).toUpperCase()}</div></div></header>
        {user.role !== 'tutor' && active !== 'settings' ? <RoleDashboard role={user.role} active={active} /> : null}
        {user.role === 'tutor' && active === 'home' && <Dashboard pets={pets} onSelect={(pet) => { setSelectedPet(pet); setActive('pets') }} onAdd={() => setShowAdd(true)} />}
        {user.role === 'tutor' && active === 'pets' && <PetsView pets={pets} selected={selectedPet} onSelect={setSelectedPet} onAdd={() => setShowAdd(true)} onQr={setQrPet} />}
        {user.role === 'tutor' && active === 'directory' && <StoreDirectoryView />}
        {user.role === 'tutor' && active === 'community' && <CommunityView />}
        {active === 'settings' && <TabbedSettingsView profile={profile} setProfile={next => { setProfile(next); localStorage.setItem('petsuite-profile', JSON.stringify(next)) }} theme={theme} setTheme={setTheme} mode={mode} setMode={setMode} brightness={brightness} setBrightness={setBrightness} onLogout={() => setUser(null)} />}
      </main>
      {showAdd && <AddPetModal onClose={() => setShowAdd(false)} onSave={addPet} />}
      {qrPet && <QrModal pet={qrPet} onClose={() => setQrPet(null)} />}
    </div>
  )
}

function setBrightnessVariables(value: number) {
  const root = document.documentElement
  root.style.setProperty('--brightness-dark', `${Math.max(0, 100 - value) * 0.7}%`)
  root.style.setProperty('--brightness-light', `${Math.max(0, value - 100) * 0.45}%`)
}

function Login({ onLogin }: { onLogin: (name: string, role: UserRole) => void }) {
  const [email, setEmail] = useState('ana@petsuite.cl'); const [password, setPassword] = useState('petsuite'); const [error, setError] = useState(''); const [demoRole, setDemoRole] = useState<UserRole>('tutor')
  const submit = (event: React.FormEvent) => { event.preventDefault(); const result = loginSchema.safeParse({ email, password }); if (!result.success) { setError(result.error.issues[0]?.message || 'Revisa los datos'); return }; onLogin(demoRole === 'business' ? 'Clínica VetCare' : demoRole === 'clinical' ? 'Dr. Luis Pérez' : demoRole === 'admin' ? 'Equipo PetSuite' : 'Ana Soto', demoRole) }
  return <div className="login-page"><div className="login-art"><div className="art-orb" /><div className="brand light"><span className="brand-mark">+</span><span>Pet<span>Suite</span></span></div><div className="art-copy"><p className="eyebrow">CUIDADO QUE CONECTA</p><h1>Todo lo que tu mascota necesita, en un solo lugar.</h1><p>Su salud, su comunidad y sus momentos importantes, siempre contigo.</p></div><div className="art-footer">PetSuite MVP <span>2025</span></div></div><form className="login-card" onSubmit={submit}><div><p className="eyebrow">BIENVENIDO DE VUELTA</p><h2>Ingresa a tu cuenta</h2><p className="muted">Administra el cuidado de quienes más quieres.</p></div><label>Correo electrónico<input value={email} onChange={e => setEmail(e.target.value)} type="email" /></label><label>Contraseña<input value={password} onChange={e => setPassword(e.target.value)} type="password" /></label>{error && <div className="form-error">{error}</div>}<button className="primary full">Ingresar <span>→</span></button><div className="login-divider"><span>cuentas demo</span></div><div className="demo-roles">{([['tutor', 'Tutor'], ['business', 'Pyme'], ['clinical', 'Clínico'], ['admin', 'Admin']] as const).map(([role, label]) => <button type="button" key={role} className={demoRole === role ? 'demo-role active' : 'demo-role'} onClick={() => setDemoRole(role)}>{label}</button>)}</div><button type="button" className="secondary full" onClick={() => onLogin(demoRole === 'business' ? 'Clínica VetCare' : demoRole === 'clinical' ? 'Dr. Luis Pérez' : demoRole === 'admin' ? 'Equipo PetSuite' : 'Ana Soto', demoRole)}>Entrar con cuenta demo</button><p className="terms">Al ingresar aceptas nuestros <u>términos de uso</u> y <u>política de privacidad</u>.</p></form></div>
}

function Dashboard({ pets, onSelect, onAdd }: { pets: Pet[]; onSelect: (pet: Pet) => void; onAdd: () => void }) {
  return <section className="page"><div className="welcome"><div><p className="eyebrow">MARTES, 15 DE SEPTIEMBRE</p><h1>Hola, Ana <span>✦</span></h1><p className="muted">Un pequeño vistazo al bienestar de tus mascotas.</p></div><button className="primary" onClick={onAdd}>+ Agregar mascota</button></div><div className="alert-card"><div className="alert-icon">♡</div><div><strong>La salud de tus mascotas, siempre a mano</strong><p>Ten sus fichas actualizadas y prepárate para cualquier emergencia.</p></div><button className="text-button">Ver ficha QR →</button></div><div className="section-heading"><div><p className="eyebrow">TUS MASCOTAS</p><h2>Compañeros de vida</h2></div><button className="text-button" onClick={() => onSelect(pets[0])}>Ver todas →</button></div><div className="pet-grid">{pets.map(pet => <PetCard key={pet.id} pet={pet} onClick={() => onSelect(pet)} />)}<button className="add-card" onClick={onAdd}><span>+</span><strong>Agregar mascota</strong><small>Registra a un nuevo compañero</small></button></div><div className="section-heading community-heading"><div><p className="eyebrow">DE TU COMUNIDAD</p><h2>Lo último en el muro</h2></div><button className="text-button">Ir al muro →</button></div><div className="post-preview"><div className="post-avatar">MC</div><div><strong>María y Coco</strong><small>Hace 24 min · Ñuñoa</small><p>¿Alguien conoce una veterinaria que atienda hoy?</p><span className="post-tag">RECOMENDACIÓN</span></div><span className="post-more">•••</span></div></section>
}

function PetsView({ pets, selected, onSelect, onAdd, onQr }: { pets: Pet[]; selected: Pet | null; onSelect: (pet: Pet) => void; onAdd: () => void; onQr: (pet: Pet) => void }) {
  return <section className="page"><div className="page-title"><div><p className="eyebrow">MÓDULO DE SALUD</p><h1>Mis mascotas</h1><p className="muted">Toda su información importante, protegida y disponible.</p></div><button className="primary" onClick={onAdd}>+ Agregar mascota</button></div><div className="pets-layout"><div className="pet-list">{pets.map(pet => <PetCard key={pet.id} pet={pet} onClick={() => onSelect(pet)} compact selected={selected?.id === pet.id} />)}</div>{selected && <PetDetail pet={selected} onQr={() => onQr(selected)} />}</div></section>
}

function PetCard({ pet, onClick, compact, selected }: { pet: Pet; onClick: () => void; compact?: boolean; selected?: boolean }) { return <button className={`pet-card ${compact ? 'compact' : ''} ${selected ? 'selected' : ''}`} onClick={onClick}><div className="pet-photo">{pet.initials}</div><div className="pet-info"><strong>{pet.name}</strong><span>{pet.breed} · {pet.age} años</span>{!compact && <small><b className="status-dot" /> Ficha actualizada</small>}</div>{compact && <span className="chevron">›</span>}</button> }

function PetDetail({ pet, onQr }: { pet: Pet; onQr: () => void }) { return <article className="detail-card"><div className="detail-head"><div className="pet-photo large">{pet.initials}</div><div><p className="eyebrow">FICHA DE MASCOTA</p><h2>{pet.name}</h2><p className="muted">{pet.species} · {pet.breed}</p></div><button className="more-button">•••</button></div><div className="detail-stats"><div><small>Edad</small><strong>{pet.age} años</strong></div><div><small>Peso</small><strong>{pet.weight} kg</strong></div><div><small>Color</small><strong>{pet.color}</strong></div></div><div className="health-row"><div><span className="health-icon">!</span><div><small>ALERGIAS</small><strong>{pet.allergies.length ? pet.allergies.join(', ') : 'Sin alergias registradas'}</strong></div></div><span className="edit-label">Editar</span></div><div className="qr-row"><div className="qr-placeholder">▦</div><div><strong>Ficha QR de emergencia</strong><p className="muted">Activa para que puedan ayudarte si se pierde.</p></div><span className="toggle on" /></div><button className="primary full" onClick={onQr}>Generar ficha QR <span>→</span></button><button className="secondary full">Ver historial médico <span>→</span></button></article> }

function QrModal({ pet, onClose }: { pet: Pet; onClose: () => void }) {
  const [src, setSrc] = useState('')
  const [contactOpen, setContactOpen] = useState(false)
  const [sent, setSent] = useState(false)
  const [message, setMessage] = useState('')

  useEffect(() => { QRCode.toDataURL(`${window.location.origin}/#emergency/${pet.id}`, { width: 280, margin: 2, color: { dark: '#171717', light: '#ffffff' } }).then(setSrc) }, [pet.id])

  const download = () => { if (!src) return; const link = document.createElement('a'); link.href = src; link.download = `petsuite-${pet.name.toLowerCase()}-qr.png`; link.click() }
  const print = () => window.print()
  const submitContact = (event: React.FormEvent) => { event.preventDefault(); if (message.trim().length < 10) return; localStorage.setItem(`petsuite-contact-${pet.id}`, message.trim()); setSent(true) }

  return <div className="modal-backdrop"><div className="modal qr-modal"><button className="close" onClick={onClose}>×</button>{sent ? <><div className="success-mark">✓</div><p className="eyebrow">CONTACTO ENVIADO</p><h2>Gracias por ayudar a {pet.name}</h2><p className="muted">El tutor recibirá tu mensaje de forma segura y podrá contactarte.</p><button className="primary full" onClick={onClose}>Volver a la ficha</button></> : contactOpen ? <form onSubmit={submitContact}><p className="eyebrow">CONTACTO SEGURO</p><h2>Ayuda a encontrar a {pet.name}</h2><p className="muted">Tu mensaje llegará al tutor sin revelar sus datos personales.</p><label className="contact-label">Tu mensaje<textarea value={message} onChange={e => setMessage(e.target.value)} placeholder="Cuéntale al tutor dónde viste a su mascota..." rows={5} /></label><div className="modal-actions"><button type="button" className="secondary" onClick={() => setContactOpen(false)}>Volver</button><button className="primary">Enviar mensaje</button></div></form> : <><p className="eyebrow">FICHA DE EMERGENCIA</p><h2>QR de {pet.name}</h2><p className="muted">Colócalo en su placa para que puedan ayudarte si se pierde.</p><div className="qr-display">{src ? <img src={src} alt={`Código QR de emergencia de ${pet.name}`} /> : <span>Generando...</span>}</div><div className="qr-actions"><button className="primary" onClick={download}>Descargar PNG</button><button className="secondary" onClick={print}>Imprimir</button></div><button className="text-button full" onClick={() => setContactOpen(true)}>Simular escaneo y contacto seguro →</button></>}</div></div>
}

function AddPetModal({ onClose, onSave }: { onClose: () => void; onSave: (pet: Pet) => void }) { const [form, setForm] = useState({ name: '', species: 'Perro', breed: '', age: '1', weight: '5', color: '' }); const [error, setError] = useState(''); const update = (key: string, value: string) => setForm({ ...form, [key]: value }); const submit = (event: React.FormEvent) => { event.preventDefault(); const parsed = petSchema.safeParse(form); if (!parsed.success) { setError(parsed.error.issues[0]?.message || 'Revisa los campos'); return }; onSave({ ...parsed.data, id: crypto.randomUUID(), initials: parsed.data.name.slice(0, 2).toUpperCase(), allergies: [], qrActive: false }) }; return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><button type="button" className="close" onClick={onClose}>×</button><p className="eyebrow">NUEVA FICHA</p><h2>Agrega un compañero</h2><p className="muted">Comienza con sus datos esenciales.</p><div className="form-grid"><label>Nombre<input value={form.name} onChange={e => update('name', e.target.value)} /></label><label>Especie<select value={form.species} onChange={e => update('species', e.target.value)}><option>Perro</option><option>Gato</option><option>Otro</option></select></label><label>Raza<input value={form.breed} onChange={e => update('breed', e.target.value)} /></label><label>Edad<input type="number" value={form.age} onChange={e => update('age', e.target.value)} /></label><label>Peso (kg)<input type="number" step="0.1" value={form.weight} onChange={e => update('weight', e.target.value)} /></label><label>Color<input value={form.color} onChange={e => update('color', e.target.value)} /></label></div>{error && <div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Guardar ficha</button></div></form></div> }

function ClinicalDashboard({ section }: { section: string }) { const patients = [{ name: 'Luna', owner: 'Ana Soto', alert: 'Alergia a pollo' }, { name: 'Bruno', owner: 'Camila Rojas', alert: 'Sin alertas' }, { name: 'Coco', owner: 'María Contreras', alert: 'Vacuna pendiente' }]; return <section className="page clinical-page"><div className="page-title"><div><p className="eyebrow">ATENCIÓN VETERINARIA</p><h1>{section === 'patients' ? 'Pacientes' : 'Tu jornada clínica'}</h1><p className="muted">{section === 'patients' ? 'Consulta fichas autorizadas y alertas relevantes.' : 'Una vista rápida de tus atenciones de hoy.'}</p></div><button className="primary">+ Nueva atención</button></div><div className="clinical-summary"><div><strong>12</strong><span>Atenciones hoy</span></div><div><strong>3</strong><span>Alertas clínicas</span></div><div><strong>94%</strong><span>Fichas actualizadas</span></div></div><div className="clinical-panel"><div className="chart-heading"><div><p className="eyebrow">AGENDA</p><h2>Pacientes recientes</h2></div><button className="text-button">Ver historial →</button></div>{patients.map(patient => <div className="patient-row" key={patient.name}><div className="pet-photo small-photo">{patient.name.slice(0, 2).toUpperCase()}</div><div><strong>{patient.name}</strong><small>{patient.owner}</small></div><span className={patient.alert === 'Sin alertas' ? 'clinical-ok' : 'clinical-alert'}>{patient.alert}</span><button className="secondary">Abrir ficha</button></div>)}</div></section> }

function BusinessOverview() { return <section className="page business-page"><div className="business-welcome"><div><p className="eyebrow">GESTIÓN DE NEGOCIO</p><h1>Clínica VetCare</h1><p>Tu espacio para crecer junto a la comunidad PetSuite.</p></div><span className="business-symbol">VC</span></div><div className="business-stats"><Metric label="Visitas al perfil" value="1.284" trend="+12% este mes" /><Metric label="Consultas recibidas" value="86" trend="+8% este mes" /><Metric label="Productos vistos" value="356" trend="+18% este mes" /></div><div className="business-activity"><p className="eyebrow">HOY</p><h2>Tu negocio está activo</h2><p>Tu catálogo tiene 12 productos publicados y tu suscripción está vigente.</p><button className="primary">Revisar catálogo →</button></div></section> }

function BusinessCatalog() {
  const [items, setItems] = useState(() => JSON.parse(localStorage.getItem('petsuite-catalog') || 'null') || [{ id: '1', name: 'Consulta general', description: 'Atención preventiva para perros y gatos.', price: '$25.000', active: true }, { id: '2', name: 'Vacunación anual', description: 'Esquema de vacunación personalizado.', price: '$18.000', active: true }])
  const [draft, setDraft] = useState({ name: '', description: '', price: '' })
  const save = (next: typeof items) => { setItems(next); localStorage.setItem('petsuite-catalog', JSON.stringify(next)) }
  return <section className="page role-page"><div className="page-title"><div><p className="eyebrow">GESTIÓN B2B</p><h1>Gestionar catálogo</h1><p className="muted">Administra los productos y servicios visibles para la comunidad.</p></div></div><form className="catalog-form" onSubmit={event => { event.preventDefault(); if (!draft.name || !draft.description || !draft.price) return; save([...items, { ...draft, id: crypto.randomUUID(), active: true }]); setDraft({ name: '', description: '', price: '' }) }}><input aria-label="Nombre del producto o servicio" value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} placeholder="Nombre del producto o servicio" /><input aria-label="Precio" value={draft.price} onChange={event => setDraft({ ...draft, price: event.target.value })} placeholder="Precio" /><button className="primary">Agregar</button></form><div className="catalog-list">{items.map((item: { id: string; name: string; description: string; price: string; active: boolean }) => <div className="catalog-item" key={item.id}><div><strong>{item.name}</strong><p>{item.description}</p><b>{item.price}</b></div><button className={item.active ? 'toggle on' : 'toggle'} aria-label={`Cambiar estado de ${item.name}`} onClick={() => save(items.map((entry: typeof item) => entry.id === item.id ? { ...entry, active: !entry.active } : entry))} /></div>)}</div></section>
}

function BusinessContacts() { const contacts = [{ name: 'Visitante anónimo', text: 'Vi a Luna cerca de la plaza.', time: 'Hace 12 min' }, { name: 'Diego Martínez', text: '¿Tienen hora disponible esta semana?', time: 'Hace 2 h' }]; return <section className="page role-page"><div className="page-title"><div><p className="eyebrow">GESTIÓN B2B</p><h1>Contactos recibidos</h1><p className="muted">Responde las solicitudes de tus clientes.</p></div></div><div className="catalog-list">{contacts.map(contact => <div className="catalog-item" key={contact.name + contact.time}><div><strong>{contact.name}</strong><p>{contact.text}</p><small>{contact.time}</small></div><button className="secondary">Responder</button></div>)}</div></section> }

function BusinessOrders() { const [status, setStatus] = useState('Recibido'); return <section className="page role-page"><div className="page-title"><div><p className="eyebrow">OPERACIÓN DE TIENDA</p><h1>Pedidos recibidos</h1><p className="muted">Gestiona solicitudes de compra y prepara cada entrega.</p></div><span className="order-count">1 pendiente</span></div><div className="order-business-card"><div className="order-heading"><div><strong>Pedido #PS-1042</strong><small>Recibido hace 12 minutos · Ana Soto</small></div><span className="order-status">{status}</span></div><div className="order-product"><span>Alimento Premium Adulto × 1</span><b>$24.990</b></div><div className="order-product"><span>Arnés ajustable rojo × 1</span><b>$12.990</b></div><div className="order-summary"><span>Despacho solicitado</span><strong>$37.980</strong></div><div className="order-progress">{['Recibido', 'Confirmado', 'Preparando', 'Enviado', 'Completado'].map(value => <button key={value} className={status === value ? 'progress-step active' : 'progress-step'} onClick={() => setStatus(value)}>{value}</button>)}</div></div></section> }

function EmergencyView({ pet }: { pet: Pet }) {
  const [message, setMessage] = useState('')
  const [sent, setSent] = useState(false)
  if (sent) return <div className="emergency-page"><div className="emergency-card"><div className="success-mark">✓</div><p className="eyebrow">CONTACTO ENVIADO</p><h1>Gracias por ayudar a {pet.name}</h1><p>El tutor recibirá tu mensaje de forma segura.</p></div></div>
  return <div className="emergency-page"><div className="emergency-card"><div className="emergency-pet-photo">{pet.initials}</div><p className="eyebrow">FICHA DE EMERGENCIA</p><h1>{pet.name}</h1><p className="emergency-subtitle">{pet.species} · {pet.breed}</p><div className="critical-info"><strong>Información importante</strong><span>{pet.allergies.length ? `Alergias: ${pet.allergies.join(', ')}` : 'No registra alergias conocidas'}</span></div><form onSubmit={event => { event.preventDefault(); if (message.trim().length >= 10) { localStorage.setItem(`petsuite-contact-${pet.id}`, message.trim()); setSent(true) } }}><label>Contactar al tutor<textarea required minLength={10} value={message} onChange={event => setMessage(event.target.value)} placeholder="Cuéntale al tutor dónde viste a su mascota..." rows={4} /></label><button className="primary full">Enviar mensaje seguro <span>→</span></button></form><p className="privacy-note">No mostraremos datos personales del tutor.</p></div></div>
}

function RoleDashboard({ role, active }: { role: string; active: string }) {
  if (role === 'admin') return <AdminDashboard section={active} />
  const business = role === 'business'; const clinical = role === 'clinical'
  if (business && active === 'catalog') return <BusinessCatalog />
  if (business && active === 'contacts') return <BusinessContacts />
  if (business && active === 'orders') return <BusinessOrders />
  if (clinical) return <ClinicalDashboard section={active} />
  if (business && active === 'business-home') return <BusinessOverview />
  const title = role === 'admin' ? 'Panel de administración' : clinical ? 'Panel clínico' : business ? 'Panel de tu negocio' : 'Panel PetSuite'
  const eyebrow = role === 'admin' ? 'VISIÓN GENERAL' : clinical ? 'ATENCIÓN VETERINARIA' : 'GESTIÓN B2B'
  const sectionNames: Record<string, string> = { catalog: 'Gestionar catálogo', metrics: 'Panel de métricas', contacts: 'Contactos recibidos', subscription: 'Gestión de suscripción', patients: 'Pacientes', users: 'Gestión de usuarios', moderation: 'Moderación del muro', subscriptions: 'Gestión de suscripciones' }
  return <section className="page role-page"><div className="page-title"><div><p className="eyebrow">{eyebrow}</p><h1>{sectionNames[active] || title}</h1><p className="muted">{active === 'catalog' ? 'Administra los productos y servicios que ofreces.' : active === 'patients' ? 'Consulta las fichas autorizadas de tus pacientes.' : 'Un resumen claro para tomar mejores decisiones.'}</p></div><button className="primary">{active === 'catalog' ? '+ Agregar producto' : 'Ver actividad →'}</button></div><div className="metric-grid"><Metric label={role === 'admin' ? 'Usuarios registrados' : clinical ? 'Pacientes atendidos' : 'Visitas este mes'} value={role === 'admin' ? '248' : clinical ? '86' : '1.284'} trend="+12%" /><Metric label={role === 'admin' ? 'Pymes activas' : clinical ? 'Fichas actualizadas' : 'Consultas de catálogo'} value={role === 'admin' ? '42' : clinical ? '94%' : '356'} trend="+8%" /><Metric label={role === 'admin' ? 'Reportes pendientes' : clinical ? 'Alertas clínicas' : 'Contactos nuevos'} value={role === 'admin' ? '7' : clinical ? '3' : '18'} trend="Esta semana" /></div><div className="role-panel"><p className="eyebrow">ACTIVIDAD RECIENTE</p><h2>{active === 'moderation' ? 'Publicaciones por revisar' : active === 'users' ? 'Usuarios recientes' : active === 'subscription' || active === 'subscriptions' ? 'Estado de suscripción' : 'Resumen de actividad'}</h2><div className="role-list"><div><span className="list-dot" /><strong>{active === 'moderation' ? '3 publicaciones esperan revisión' : active === 'catalog' ? 'Tu catálogo tiene 12 productos activos' : 'Todo está al día'}</strong><small>Actualizado hace unos minutos</small></div><div><span className="list-dot soft" /><strong>{active === 'contacts' ? '18 contactos nuevos para responder' : 'No hay tareas urgentes pendientes'}</strong><small>PetSuite mantiene tu información organizada</small></div></div></div></section>
}

function Metric({ label, value, trend }: { label: string; value: string; trend: string }) { return <div className="metric-card"><small>{label}</small><strong>{value}</strong><span>{trend}</span></div> }

function AdminDashboard({ section }: { section: string }) { const [users, setUsers] = useState(() => JSON.parse(localStorage.getItem('petsuite-admin-users') || 'null') || [{ id: 'u1', name: 'Ana Soto', email: 'ana@petsuite.cl', role: 'Tutor', status: 'Activo' }, { id: 'u2', name: 'Clínica VetCare', email: 'admin@vetcare.cl', role: 'Pyme', status: 'Activo' }, { id: 'u3', name: 'Carlos Muñoz', email: 'carlos@email.cl', role: 'Tutor', status: 'Reportado' }, { id: 'u4', name: 'Pet Market', email: 'hola@petmarket.cl', role: 'Pyme', status: 'Suspendido' }]); const [selected, setSelected] = useState<string | null>(null); const update = (id: string, status: string) => { const next = users.map((user: typeof users[number]) => user.id === id ? { ...user, status } : user); setUsers(next); localStorage.setItem('petsuite-admin-users', JSON.stringify(next)); setSelected(null) }; if (section === 'users') return <AdminUsers users={users} onSuspend={setSelected} onReactivate={id => update(id, 'Activo')} />; if (section === 'moderation') return <AdminReports users={users.filter((user: typeof users[number]) => user.status === 'Reportado')} onResolve={id => update(id, 'Activo')} onSuspend={setSelected} />; const bars = [42, 58, 49, 73, 66, 88, 79, 96, 84, 91, 86, 100]; const sessions = [35, 48, 42, 62, 57, 73, 68, 82, 76, 90, 84, 93]; return <section className="page admin-page"><div className="page-title"><div><p className="eyebrow">CENTRO DE CONTROL</p><h1>{section === 'subscriptions' ? 'Suscripciones' : 'Resumen de PetSuite'}</h1><p className="muted">Datos ficticios de la base de datos de PetSuite.</p></div><button className="secondary">Últimos 30 días⌄</button></div><div className="admin-metrics"><Metric label="Usuarios registrados" value="248" trend="+12,4% vs. mes anterior" /><Metric label="Sesiones activas" value="1.284" trend="+8,2% vs. mes anterior" /><Metric label="Compras realizadas" value="356" trend="+18,6% vs. mes anterior" /><Metric label="Ingresos del mes" value="$4,8M" trend="+14,1% vs. mes anterior" /></div><div className="admin-chart-grid"><article className="admin-chart-card"><div className="chart-heading"><div><p className="eyebrow">CRECIMIENTO</p><h2>Usuarios registrados</h2></div><strong>+12,4%</strong></div><div className="bar-chart" aria-label="Usuarios registrados en los últimos doce meses">{bars.map((height, index) => <div className="bar-column" key={index}><span style={{ height: `${height}%` }} /><small>{['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'][index]}</small></div>)}</div></article><article className="admin-chart-card"><div className="chart-heading"><div><p className="eyebrow">ACTIVIDAD</p><h2>Sesiones en la plataforma</h2></div><strong>1.284</strong></div><div className="line-chart"><svg viewBox="0 0 500 170" role="img" aria-label="Sesiones en los últimos doce meses"><polyline points={sessions.map((height, index) => `${index * 45},${155 - height * 1.35}`).join(' ')} fill="none" stroke="var(--color-accent-solid)" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" /></svg><div className="chart-axis"><span>Ene</span><span>Mar</span><span>May</span><span>Jul</span><span>Sep</span><span>Dic</span></div></div></article></div><div className="admin-bottom-grid"><article className="admin-table-card"><div className="chart-heading"><div><p className="eyebrow">MONETIZACIÓN</p><h2>Compras recientes</h2></div></div>{[['Plan Profesional', 'Clínica VetCare', '$89.990'], ['Pack destacado', 'Pet Market', '$24.990'], ['Plan Básico', 'Huellas & Estilo', '$39.990']].map(row => <div className="purchase-row" key={row[1]}><span className="purchase-icon">$</span><div><strong>{row[0]}</strong><small>{row[1]}</small></div><b>{row[2]}</b></div>)}</article><article className="admin-table-card"><div className="chart-heading"><div><p className="eyebrow">USUARIOS</p><h2>Estado de cuentas</h2></div></div><div className="health-stat"><span className="status-dot" /><div><strong>246 activas</strong><small>Usuarios con acceso vigente</small></div></div><div className="health-stat warning"><span className="status-dot" /><div><strong>{users.filter((user: typeof users[number]) => user.status === 'Reportado').length} reportados</strong><small>Revisión administrativa pendiente</small></div></div></article></div>{selected && <SuspensionModal onClose={() => setSelected(null)} onConfirm={(status: string) => update(selected, status)} />}</section> }

function LegacyAdminUsers({ users, onSuspend, onReactivate }: { users: { id: string; name: string; email: string; role: string; status: string }[]; onSuspend: (id: string) => void; onReactivate: (id: string) => void }) { return <section className="page admin-page"><div className="page-title"><div><p className="eyebrow">ADMINISTRACIÓN</p><h1>Gestión de usuarios</h1><p className="muted">Supervisa cuentas, roles y estados de acceso.</p></div></div><div className="admin-table-card user-table">{users.map(user => <div className="user-row" key={user.id}><div className="avatar">{user.name.slice(0, 2).toUpperCase()}</div><div><strong>{user.name}</strong><small>{user.email} · {user.role}</small></div><span className={`user-status ${user.status.toLowerCase()}`}>{user.status}</span><button className="secondary" onClick={() => user.status === 'Activo' ? onSuspend(user.id) : onReactivate(user.id)}>{user.status === 'Activo' ? 'Suspender' : 'Reactivar'}</button></div>)}</div></section> }

function AdminUsers({ users, onSuspend, onReactivate }: { users: { id: string; name: string; email: string; role: string; status: string }[]; onSuspend: (id: string) => void; onReactivate: (id: string) => void }) { const [query, setQuery] = useState(''); const [filter, setFilter] = useState<'Todos' | 'Activos' | 'Reportados' | 'Suspendidos'>('Todos'); const filtered = users.filter(user => (filter === 'Todos' || (filter === 'Activos' && user.status === 'Activo') || (filter === 'Reportados' && user.status === 'Reportado') || (filter === 'Suspendidos' && user.status.includes('Suspendido'))) && `${user.name} ${user.email} ${user.role}`.toLowerCase().includes(query.toLowerCase())); return <section className="page admin-page"><div className="page-title"><div><p className="eyebrow">ADMINISTRACIÓN</p><h1>Gestión de usuarios</h1><p className="muted">Busca, filtra y administra las cuentas de PetSuite.</p></div><span className="admin-total">{users.length} cuentas</span></div><div className="user-toolbar"><div className="search-field"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por nombre, correo o rol" /></div></div><div className="user-filters">{(['Todos', 'Activos', 'Reportados', 'Suspendidos'] as const).map(value => <button key={value} className={filter === value ? 'category-tab active' : 'category-tab'} onClick={() => setFilter(value)}>{value}<b>{value === 'Todos' ? users.length : value === 'Activos' ? users.filter(user => user.status === 'Activo').length : value === 'Reportados' ? users.filter(user => user.status === 'Reportado').length : users.filter(user => user.status.includes('Suspendido')).length}</b></button>)}</div><div className="admin-table-card user-table polished-user-table"><div className="user-table-head"><span>USUARIO</span><span>ROL</span><span>ESTADO</span><span>ACCIÓN</span></div>{filtered.map(user => <div className="user-row" key={user.id}><div className="avatar">{user.name.slice(0, 2).toUpperCase()}</div><div className="user-identity"><strong>{user.name}</strong><small>{user.email}</small></div><span className="user-role">{user.role}</span><span className={`user-status ${user.status.toLowerCase()}`}>{user.status}</span><button className={user.status === 'Activo' ? 'secondary' : 'primary'} onClick={() => user.status === 'Activo' || user.status === 'Reportado' ? onSuspend(user.id) : onReactivate(user.id)}>{user.status === 'Activo' || user.status === 'Reportado' ? 'Suspender' : 'Reactivar'}</button></div>)}{filtered.length === 0 && <div className="empty-results">No encontramos usuarios con estos filtros.</div>}</div></section> }

function AdminReports({ users, onResolve, onSuspend }: { users: { id: string; name: string; email: string; role: string; status: string }[]; onResolve: (id: string) => void; onSuspend: (id: string) => void }) { return <section className="page admin-page"><div className="page-title"><div><p className="eyebrow">MODERACIÓN</p><h1>Usuarios reportados</h1><p className="muted">Revisa reportes y decide si resolver o suspender una cuenta.</p></div></div><div className="admin-table-card user-table">{users.length ? users.map(user => <div className="user-row" key={user.id}><div className="avatar">{user.name.slice(0, 2).toUpperCase()}</div><div><strong>{user.name}</strong><small>{user.email} · Reporte pendiente</small></div><button className="secondary" onClick={() => onResolve(user.id)}>Resolver</button><button className="primary" onClick={() => onSuspend(user.id)}>Suspender</button></div>) : <div className="empty-results">No hay usuarios reportados.</div>}</div></section> }

function SuspensionModal({ onClose, onConfirm }: { onClose: () => void; onConfirm: (status: string) => void }) { const [permanent, setPermanent] = useState(false); const [days, setDays] = useState('30'); return <div className="modal-backdrop"><div className="modal suspension-modal"><button className="close" onClick={onClose}>×</button><p className="eyebrow">ACCIÓN ADMINISTRATIVA</p><h2>Confirmar suspensión</h2><p className="muted">La cuenta perderá acceso durante el tiempo que definas.</p><div className="suspension-choice"><label>Duración en días<input type="number" min="1" max="3650" value={days} disabled={permanent} onChange={event => setDays(event.target.value)} /></label><label className="permanent-choice"><input type="checkbox" checked={permanent} onChange={event => setPermanent(event.target.checked)} /> Suspensión permanente</label></div><div className="suspension-warning">{permanent ? 'La cuenta no podrá acceder hasta que un administrador la reactive.' : `El acceso se bloqueará por ${days || '0'} días.`}</div><div className="modal-actions"><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" onClick={() => onConfirm(permanent ? 'Suspendido · Permanente' : `Suspendido · ${days} días`)}>Confirmar suspensión</button></div></div></div> }

function SimpleView({ title, eyebrow, text }: { title: string; eyebrow: string; text: string }) { return <section className="page"><div className="page-title"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="muted">{text}</p></div></div><div className="coming-soon"><span>+</span><h2>Estamos preparando este espacio</h2><p>Esta sección forma parte del MVP y se implementará en la siguiente fase.</p></div></section> }

function LegacyDirectoryView() {
  const [category, setCategory] = useState<'Todas' | BusinessCategory>('Todas')
  const [commune, setCommune] = useState('Todas')
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState<Business | null>(null)
  const filtered = businesses.filter(business => (category === 'Todas' || business.category === category) && (commune === 'Todas' || business.commune === commune) && `${business.name} ${business.category} ${business.description}`.toLowerCase().includes(query.toLowerCase()))
  const communes = [...new Set(businesses.map(business => business.commune))]

  return <section className="page directory-page"><div className="page-title"><div><p className="eyebrow">ENCUENTRA CERCA DE TI</p><h1>Directorio de Pymes</h1><p className="muted">Lugares confiables para el cuidado de tu mascota.</p></div><button className="secondary">¿Tienes un negocio? <span>→</span></button></div><div className="directory-toolbar"><div className="search-field"><span>⌕</span><input placeholder="Busca por nombre o servicio" /></div><select value={commune} onChange={event => setCommune(event.target.value)}><option>Todas</option>{communes.map(value => <option key={value}>{value}</option>)}</select></div><div className="category-tabs">{(['Todas', 'Veterinaria', 'Tienda', 'Peluquería'] as const).map(value => <button key={value} onClick={() => setCategory(value)} className={category === value ? 'category-tab active' : 'category-tab'}>{value}</button>)}</div><div className="directory-layout"><div className="business-results"><div className="results-count"><strong>{filtered.length} lugares</strong><span>Ordenados por cercanía</span></div>{filtered.map(business => <BusinessCard key={business.id} business={business} onClick={() => setSelected(business)} />)}{filtered.length === 0 && <div className="empty-results">No encontramos negocios con estos filtros.</div>}</div><div className="map-card"><div className="map-header"><strong>Mapa de la zona</strong><span>Vista simulada</span></div><div className="fake-map"><div className="map-road road-one" /><div className="map-road road-two" /><div className="map-road road-three" />{filtered.map((business, index) => <button key={business.id} className={`map-pin pin-${index + 1}`} onClick={() => setSelected(business)} title={business.name}>{index + 1}</button>)}<div className="map-label label-one">Ñuñoa</div><div className="map-label label-two">Providencia</div></div></div></div>{selected && <BusinessModal business={selected} onClose={() => setSelected(null)} />}</section>
}

function StoreDirectoryView() { const [query, setQuery] = useState(''); const [commune, setCommune] = useState('Todas'); const [selected, setSelected] = useState<Business | null>(null); const [cart, setCart] = useState<Product[]>([]); const [checkout, setCheckout] = useState(false); const communes = [...new Set(businesses.map(item => item.commune))]; const stores = businesses.filter(item => item.category === 'Tienda de mascotas' && (commune === 'Todas' || item.commune === commune) && `${item.name} ${item.commune} ${item.description}`.toLowerCase().includes(query.toLowerCase())); const addToCart = (product: Product) => setCart([...cart, product]); const total = cart.reduce((sum, item) => sum + item.price, 0); return <section className="page directory-page"><div className="directory-hero"><div><p className="eyebrow">COMPRA CERCA DE TI</p><h1>Encuentra productos para tu mascota</h1><p>Comida, accesorios, higiene y salud en tiendas locales de confianza.</p></div><div className="cart-summary"><span>Carrito</span><strong>{cart.length}</strong></div></div><div className="directory-toolbar"><div className="search-field"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Busca una tienda, producto o comuna" /></div><select value={commune} onChange={event => setCommune(event.target.value)}><option value="Todas">Todas las comunas</option>{communes.map(value => <option key={value}>{value}</option>)}</select></div><div className="directory-layout"><div className="business-results"><div className="results-count"><strong>{stores.length} tiendas cerca de ti</strong><span>Venta y distribución local</span></div>{stores.map(store => <StoreCard key={store.id} store={store} onOpen={() => setSelected(store)} />)}</div><div className="map-card"><div className="map-header"><strong>Tiendas en el mapa</strong><span>{stores.length} disponibles</span></div><div className="fake-map"><div className="map-road road-one" /><div className="map-road road-two" /><div className="map-road road-three" />{stores.map((store, index) => <button key={store.id} className={`map-pin pin-${index + 1}`} onClick={() => setSelected(store)} title={store.name}>{index + 1}</button>)}<div className="map-label label-one">Ñuñoa</div><div className="map-label label-two">Providencia</div></div></div></div>{cart.length > 0 && <div className="cart-bar"><div><strong>{cart.length} productos en tu carrito</strong><span>Total: ${total.toLocaleString('es-CL')}</span></div><button className="primary" onClick={() => setCheckout(true)}>Revisar pedido →</button></div>}{selected && <StoreModal store={selected} onClose={() => setSelected(null)} onAdd={addToCart} />}{checkout && <OrderModal cart={cart} total={total} onClose={() => setCheckout(false)} onSent={() => { localStorage.setItem('petsuite-order-demo', JSON.stringify({ cart, total, status: 'Recibido' })); setCart([]); setCheckout(false) }} />}</section> }

function StoreCard({ store, onOpen }: { store: Business; onOpen: () => void }) { return <button className="business-card store-card" onClick={onOpen}><div className="business-logo">{store.initials}</div><div className="business-info"><div className="business-card-top"><strong>{store.name}</strong>{store.featured && <span className="featured">DESTACADA</span>}</div><span>{store.commune} · {store.distance}</span><small>{store.description}</small><div className="business-meta"><b className={store.open ? 'open' : 'closed'}>{store.open ? 'Recibe pedidos' : 'Cerrada ahora'}</b><i />{store.address}</div></div><span className="chevron">›</span></button> }

function StoreModal({ store, onClose, onAdd }: { store: Business; onClose: () => void; onAdd: (product: Product) => void }) { const storeProducts = products.filter(product => product.businessId === store.id); return <div className="modal-backdrop"><article className="modal store-modal"><button className="close" onClick={onClose}>×</button><div className="business-hero"><span>{store.initials}</span></div><p className="eyebrow">TIENDA DE MASCOTAS · {store.commune.toUpperCase()}</p><h2>{store.name}</h2><p className="muted">{store.description}</p><div className="store-info"><span>⌖ {store.address}</span><span>◷ {store.open ? 'Abierta y recibiendo pedidos' : 'Cerrada ahora'}</span></div><div className="product-list">{storeProducts.map(product => <div className="product-row" key={product.id}><div><strong>{product.name}</strong><small>{product.category} · {product.description}</small></div><b>${product.price.toLocaleString('es-CL')}</b><button className="primary" onClick={() => onAdd(product)}>Agregar</button></div>)}</div><button className="secondary full" onClick={onClose}>Seguir explorando</button></article></div> }

function OrderModal({ cart, total, onClose, onSent }: { cart: Product[]; total: number; onClose: () => void; onSent: () => void }) { const [delivery, setDelivery] = useState<'Retiro en tienda' | 'Despacho'>('Retiro en tienda'); return <div className="modal-backdrop"><form className="modal order-modal" onSubmit={event => { event.preventDefault(); onSent() }}><button type="button" className="close" onClick={onClose}>×</button><p className="eyebrow">SOLICITUD DE PEDIDO</p><h2>Confirma tu pedido</h2><div className="order-items">{cart.map((product, index) => <div key={`${product.id}-${index}`}><span>{product.name}</span><b>${product.price.toLocaleString('es-CL')}</b></div>)}</div><label>Modalidad<select value={delivery} onChange={event => setDelivery(event.target.value as typeof delivery)}><option>Retiro en tienda</option><option>Despacho</option></select></label><div className="order-total"><span>Total estimado</span><strong>${total.toLocaleString('es-CL')}</strong></div><button className="primary full">Enviar solicitud a la tienda</button><p className="muted order-note">El pago se coordina directamente con la tienda en este mockup.</p></form></div> }

function CommunityView() {
  const [posts, setPosts] = useState<CommunityPost[]>(() => JSON.parse(localStorage.getItem('petsuite-posts') || 'null') || initialPosts)
  const [filter, setFilter] = useState<'Todos' | PostType>('Todos')
  const [showComposer, setShowComposer] = useState(false)
  const [commenting, setCommenting] = useState<string | null>(null)
  const visiblePosts = posts.filter(post => filter === 'Todos' || post.type === filter)
  const save = (next: CommunityPost[]) => { setPosts(next); localStorage.setItem('petsuite-posts', JSON.stringify(next)) }
  const react = (id: string) => save(posts.map(post => post.id === id ? { ...post, reacted: !post.reacted, reactions: post.reactions + (post.reacted ? -1 : 1) } : post))
  const addComment = (id: string, text: string) => save(posts.map(post => post.id === id ? { ...post, comments: [...post.comments, { id: crypto.randomUUID(), author: 'Ana Soto', text }] } : post))
  const report = (id: string) => save(posts.map(post => post.id === id ? { ...post, reported: true } : post))
  return <section className="page community-page"><div className="page-title"><div><p className="eyebrow">COMUNIDAD PETSUITE</p><h1>Muro comunal</h1><p className="muted">Comparte, encuentra y ayuda a otros tutores de tu comuna.</p></div><button className="primary" onClick={() => setShowComposer(true)}>+ Publicar</button></div><div className="community-intro"><div className="intro-icon">♡</div><div><strong>Una comunidad que se cuida</strong><p>Juntos podemos hacer que cada mascota vuelva a casa.</p></div></div><div className="community-filters">{(['Todos', 'Extravío', 'Encuentro', 'Recomendación'] as const).map(value => <button key={value} className={filter === value ? 'category-tab active' : 'category-tab'} onClick={() => setFilter(value)}>{value}</button>)}</div><div className="community-feed">{visiblePosts.map(post => <PostCard key={post.id} post={post} onReact={() => react(post.id)} onComment={() => setCommenting(commenting === post.id ? null : post.id)} onReport={() => report(post.id)} showComment={commenting === post.id} onAddComment={text => addComment(post.id, text)} />)}{visiblePosts.length === 0 && <div className="empty-results">Todavía no hay publicaciones de este tipo.</div>}</div>{showComposer && <PostComposer onClose={() => setShowComposer(false)} onSave={post => { save([post, ...posts]); setShowComposer(false) }} />}</section>
}

function PostCard({ post, onReact, onComment, onReport, showComment, onAddComment }: { post: CommunityPost; onReact: () => void; onComment: () => void; onReport: () => void; showComment: boolean; onAddComment: (text: string) => void }) { const [text, setText] = useState(''); const submit = (event: React.FormEvent) => { event.preventDefault(); const result = communityCommentSchema.safeParse({ text }); if (!result.success) return; onAddComment(text); setText('') }; return <article className="community-post"><div className="post-top"><div className="post-avatar">{post.initials}</div><div><strong>{post.author}</strong><small>{post.time} · {post.location}</small></div><button className="post-menu" onClick={onReport} title="Reportar publicación">•••</button></div><span className={`post-type ${post.type === 'Extravío' ? 'lost' : post.type === 'Encuentro' ? 'found' : 'recommendation'}`}>{post.type.toUpperCase()}</span><h3>{post.title}</h3><p>{post.body}</p>{post.reported && <div className="reported-note">Publicación reportada para revisión</div>}<div className="post-actions"><button className={post.reacted ? 'reacted' : ''} onClick={onReact}>♡ {post.reactions}</button><button onClick={onComment}>○ {post.comments.length} comentarios</button><button onClick={onReport}>Reportar</button></div>{post.comments.length > 0 && <div className="comments">{post.comments.map(comment => <div className="comment" key={comment.id}><strong>{comment.author}</strong><span>{comment.text}</span></div>)}</div>}{showComment && <form className="comment-form" onSubmit={submit}><input value={text} onChange={event => setText(event.target.value)} placeholder="Escribe un comentario..." /><button className="primary">Enviar</button></form>}</article> }

function PostComposer({ onClose, onSave }: { onClose: () => void; onSave: (post: CommunityPost) => void }) { const [form, setForm] = useState({ type: 'Recomendación' as PostType, title: '', body: '', location: 'Ñuñoa' }); const [error, setError] = useState(''); const update = (key: string, value: string) => setForm({ ...form, [key]: value }); const submit = (event: React.FormEvent) => { event.preventDefault(); const result = communityPostSchema.safeParse(form); if (!result.success) { setError(result.error.issues[0]?.message || 'Revisa los campos'); return }; onSave({ ...result.data, id: crypto.randomUUID(), author: 'Ana Soto', initials: 'AS', time: 'Ahora', reactions: 0, reacted: false, comments: [], reported: false }) }; return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><button type="button" className="close" onClick={onClose}>×</button><p className="eyebrow">NUEVA PUBLICACIÓN</p><h2>Comparte con tu comunidad</h2><p className="muted">Una buena información puede ayudar mucho.</p><div className="form-grid"><label>Tipo<select value={form.type} onChange={event => update('type', event.target.value)}><option>Recomendación</option><option>Extravío</option><option>Encuentro</option></select></label><label>Comuna<input value={form.location} onChange={event => update('location', event.target.value)} /></label></div><label className="composer-label">Título<input value={form.title} onChange={event => update('title', event.target.value)} /></label><label className="composer-label">Descripción<textarea rows={5} value={form.body} onChange={event => update('body', event.target.value)} /></label>{error && <div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Publicar</button></div></form></div> }

function BusinessCard({ business, onClick }: { business: Business; onClick: () => void }) { return <button className="business-card" onClick={onClick}><div className={`business-logo ${business.category === 'Tienda' ? 'gold' : business.category === 'Peluquería' ? 'dark' : ''}`}>{business.initials}</div><div className="business-info"><div className="business-card-top"><strong>{business.name}</strong>{business.featured && <span className="featured">DESTACADO</span>}</div><span>{business.category} · {business.commune}</span><small>{business.address}</small><div className="business-meta"><b className={business.open ? 'open' : 'closed'}>{business.open ? 'Abierto ahora' : 'Cerrado'}</b><i />{business.distance}</div></div><span className="chevron">›</span></button> }

function BusinessModal({ business, onClose }: { business: Business; onClose: () => void }) { return <div className="modal-backdrop"><article className="modal business-modal"><button className="close" onClick={onClose}>×</button><div className={`business-hero ${business.category === 'Tienda' ? 'gold' : business.category === 'Peluquería' ? 'dark' : ''}`}><span>{business.initials}</span></div><p className="eyebrow">{business.category.toUpperCase()}</p><h2>{business.name}</h2><p className="muted">{business.description}</p><div className="business-detail-line"><span>⌖</span><div><strong>Dirección</strong><p>{business.address} · {business.distance}</p></div></div><div className="business-detail-line"><span>◷</span><div><strong>Estado</strong><p className={business.open ? 'open-text' : ''}>{business.open ? 'Abierto ahora' : 'Cerrado por hoy'}</p></div></div><button className="primary full" onClick={() => { localStorage.setItem(`petsuite-business-contact-${business.id}`, 'Solicitud de contacto demo'); onClose() }}>Contactar negocio <span>→</span></button></article></div> }

function TabbedSettingsView({ profile, setProfile, theme, setTheme, mode, setMode, brightness, setBrightness, onLogout }: { profile: { name: string; email: string; phone: string; avatar: string }; setProfile: (profile: { name: string; email: string; phone: string; avatar: string }) => void; theme: ThemeName; setTheme: (theme: ThemeName) => void; mode: ColorMode; setMode: (mode: ColorMode) => void; brightness: number; setBrightness: (brightness: number) => void; onLogout: () => void }) {
  const [section, setSection] = useState('profile')
  const [draft, setDraft] = useState(profile)
  const [saved, setSaved] = useState(false)
  const [notifications, setNotifications] = useState(() => localStorage.getItem('petsuite-notifications') !== 'false')
  const [publicProfile, setPublicProfile] = useState(() => localStorage.getItem('petsuite-public-profile') !== 'false')
  const [draftTheme, setDraftTheme] = useState(theme)
  const [draftMode, setDraftMode] = useState(mode)
  const [draftBrightness, setDraftBrightness] = useState(brightness)
  useEffect(() => { const dark = draftMode === 'dark' || (draftMode === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches); document.documentElement.dataset.theme = draftTheme; document.documentElement.dataset.mode = dark ? 'dark' : 'light'; setBrightnessVariables(draftBrightness) }, [draftTheme, draftMode, draftBrightness])
  useEffect(() => () => { const dark = mode === 'dark' || (mode === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches); document.documentElement.dataset.theme = theme; document.documentElement.dataset.mode = dark ? 'dark' : 'light'; setBrightnessVariables(brightness) }, [])
  const saveProfile = (event: React.FormEvent) => { event.preventDefault(); setProfile({ ...draft, avatar: draft.name.split(' ').map(part => part[0]).join('').slice(0, 2).toUpperCase() }); setSaved(true); window.setTimeout(() => setSaved(false), 2200) }
  const toggle = (key: 'notifications' | 'publicProfile', value: boolean) => { if (key === 'notifications') { setNotifications(value); localStorage.setItem('petsuite-notifications', String(value)) } else { setPublicProfile(value); localStorage.setItem('petsuite-public-profile', String(value)) } }
  const confirmAppearance = () => { setTheme(draftTheme); setMode(draftMode); setBrightness(draftBrightness); setSaved(true); window.setTimeout(() => setSaved(false), 2200) }
  const sections = [['profile', 'Perfil'], ['appearance', 'Apariencia'], ['notifications', 'Notificaciones'], ['privacy', 'Privacidad']] as const
  return <section className="page settings-page"><div className="page-title"><div><p className="eyebrow">TU CUENTA</p><h1>Configuración</h1><p className="muted">Personaliza tu experiencia en PetSuite.</p></div></div><div className="settings-layout"><div className="settings-nav">{sections.map(([id, label]) => <button key={id} className={section === id ? 'settings-nav-item active' : 'settings-nav-item'} onClick={() => setSection(id)}>{label}</button>)}</div><div className="settings-content">{section === 'profile' && <form className="settings-card" onSubmit={saveProfile}><div className="settings-card-heading"><div><p className="eyebrow">INFORMACIÓN PERSONAL</p><h2>Perfil</h2></div><div className="profile-avatar">{draft.avatar}</div></div><div className="settings-form-grid"><label>Nombre completo<input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} /></label><label>Correo electrónico<input type="email" value={draft.email} onChange={event => setDraft({ ...draft, email: event.target.value })} /></label><label>Teléfono<input value={draft.phone} onChange={event => setDraft({ ...draft, phone: event.target.value })} /></label></div><div className="settings-actions"><span className="save-message">{saved ? 'Cambios guardados' : ''}</span><button className="primary">Guardar cambios</button></div></form>}{section === 'appearance' && <div className="settings-card"><div className="settings-card-heading"><div><p className="eyebrow">PERSONALIZA LA INTERFAZ</p><h2>Apariencia</h2><p className="muted">Previsualiza y confirma tus preferencias visuales.</p></div></div><div className="theme-options">{themeOptions.map(option => <button type="button" key={option.name} className={draftTheme === option.name ? 'theme-option selected' : 'theme-option'} onClick={() => setDraftTheme(option.name)}><span className="theme-swatch" style={{ background: option.color }} /><span>{option.label}</span>{draftTheme === option.name && <b>✓</b>}</button>)}</div><div className="mode-options"><button type="button" className={draftMode === 'light' ? 'mode-option active' : 'mode-option'} onClick={() => setDraftMode('light')}>Claro</button><button type="button" className={draftMode === 'dark' ? 'mode-option active' : 'mode-option'} onClick={() => setDraftMode('dark')}>Oscuro</button><button type="button" className={draftMode === 'system' ? 'mode-option active' : 'mode-option'} onClick={() => setDraftMode('system')}>Sistema</button></div><label className="brightness-control">Brillo de la interfaz <output>{draftBrightness}%</output><input type="range" min="70" max="115" value={draftBrightness} onChange={event => setDraftBrightness(Number(event.target.value))} /></label><div className="settings-actions"><span className="save-message">{saved ? 'Preferencias confirmadas' : ''}</span><button type="button" className="primary" onClick={confirmAppearance}>Confirmar cambios</button></div></div>}{section === 'notifications' && <div className="settings-card"><div className="settings-card-heading"><div><p className="eyebrow">PREFERENCIAS</p><h2>Notificaciones</h2><p className="muted">Controla los avisos que recibes de PetSuite.</p></div></div><SettingRow title="Avisos de la comunidad" text="Recibe novedades sobre publicaciones y contactos." value={notifications} onChange={value => toggle('notifications', value)} /></div>}{section === 'privacy' && <><div className="settings-card"><div className="settings-card-heading"><div><p className="eyebrow">VISIBILIDAD</p><h2>Privacidad</h2><p className="muted">Decide qué información pueden ver otros tutores.</p></div></div><SettingRow title="Perfil público" text="Permite que otros vean tu nombre en el muro comunal." value={publicProfile} onChange={value => toggle('publicProfile', value)} /></div><div className="settings-card danger-card"><div><p className="eyebrow">SESIÓN</p><h2>Salir de PetSuite</h2><p className="muted">Cierra la sesión de este dispositivo.</p></div><button type="button" className="secondary danger-button" onClick={onLogout}>Cerrar sesión</button></div></>}</div></div></section>
}

function SettingsView({ profile, setProfile, theme, setTheme, mode, setMode, onLogout }: { profile: { name: string; email: string; phone: string; avatar: string }; setProfile: (profile: { name: string; email: string; phone: string; avatar: string }) => void; theme: ThemeName; setTheme: (theme: ThemeName) => void; mode: ColorMode; setMode: (mode: ColorMode) => void; onLogout: () => void }) {
  const [draft, setDraft] = useState(profile)
  const [saved, setSaved] = useState(false)
  const [notifications, setNotifications] = useState(() => localStorage.getItem('petsuite-notifications') !== 'false')
  const [publicProfile, setPublicProfile] = useState(() => localStorage.getItem('petsuite-public-profile') !== 'false')
  const saveProfile = (event: React.FormEvent) => { event.preventDefault(); setProfile({ ...draft, avatar: draft.name.split(' ').map(part => part[0]).join('').slice(0, 2).toUpperCase() }); setSaved(true); window.setTimeout(() => setSaved(false), 2200) }
  const toggle = (key: 'notifications' | 'publicProfile', value: boolean) => { if (key === 'notifications') { setNotifications(value); localStorage.setItem('petsuite-notifications', String(value)) } else { setPublicProfile(value); localStorage.setItem('petsuite-public-profile', String(value)) } }
  return <section className="page settings-page"><div className="page-title"><div><p className="eyebrow">TU CUENTA</p><h1>Configuración</h1><p className="muted">Personaliza tu experiencia en PetSuite.</p></div></div><div className="settings-layout"><div className="settings-nav"><button className="settings-nav-item active">Perfil</button><button className="settings-nav-item">Apariencia</button><button className="settings-nav-item">Notificaciones</button><button className="settings-nav-item">Privacidad</button></div><div className="settings-content"><form className="settings-card" onSubmit={saveProfile}><div className="settings-card-heading"><div><p className="eyebrow">INFORMACIÓN PERSONAL</p><h2>Perfil</h2></div><div className="profile-avatar">{draft.avatar}</div></div><div className="settings-form-grid"><label>Nombre completo<input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} /></label><label>Correo electrónico<input type="email" value={draft.email} onChange={event => setDraft({ ...draft, email: event.target.value })} /></label><label>Teléfono<input value={draft.phone} onChange={event => setDraft({ ...draft, phone: event.target.value })} /></label></div><div className="settings-actions"><span className="save-message">{saved ? 'Cambios guardados' : ''}</span><button className="primary">Guardar cambios</button></div></form><div className="settings-card"><div className="settings-card-heading"><div><p className="eyebrow">PERSONALIZA LA INTERFAZ</p><h2>Apariencia</h2><p className="muted">Elige el color que mejor represente tu experiencia.</p></div></div><div className="theme-options">{themeOptions.map(option => <button type="button" key={option.name} className={theme === option.name ? 'theme-option selected' : 'theme-option'} onClick={() => setTheme(option.name)}><span className="theme-swatch" style={{ background: option.color }} /><span>{option.label}</span>{theme === option.name && <b>✓</b>}</button>)}</div><div className="mode-options"><button type="button" className={mode === 'light' ? 'mode-option active' : 'mode-option'} onClick={() => setMode('light')}>Claro</button><button type="button" className={mode === 'dark' ? 'mode-option active' : 'mode-option'} onClick={() => setMode('dark')}>Oscuro</button><button type="button" className={mode === 'system' ? 'mode-option active' : 'mode-option'} onClick={() => setMode('system')}>Sistema</button></div></div><div className="settings-card"><div className="settings-card-heading"><div><p className="eyebrow">PREFERENCIAS</p><h2>Notificaciones y privacidad</h2></div></div><SettingRow title="Avisos de la comunidad" text="Recibe novedades sobre publicaciones y contactos." value={notifications} onChange={value => toggle('notifications', value)} /><SettingRow title="Perfil público" text="Permite que otros vean tu nombre en el muro comunal." value={publicProfile} onChange={value => toggle('publicProfile', value)} /></div><div className="settings-card danger-card"><div><p className="eyebrow">SESIÓN</p><h2>Salir de PetSuite</h2><p className="muted">Cierra la sesión de este dispositivo.</p></div><button type="button" className="secondary danger-button" onClick={onLogout}>Cerrar sesión</button></div></div></div></section>
}

function SettingRow({ title, text, value, onChange }: { title: string; text: string; value: boolean; onChange: (value: boolean) => void }) { return <div className="setting-row"><div><strong>{title}</strong><p>{text}</p></div><button type="button" aria-label={`Cambiar ${title}`} className={value ? 'toggle on' : 'toggle'} onClick={() => onChange(!value)} /></div> }

export default App
